WITH cleaned AS (SELECT id, price, cost, launch_date, tags, supplier_id, ARRAY_JOIN(tags, '|') AS tags_text, stock_qty * price AS stock_qty_times_price FROM products WHERE stock_qty <= 111), matched_keys AS (SELECT supplier_id, id FROM cleaned EXCEPT DISTINCT SELECT supplier_id, id FROM products WHERE price BETWEEN 390 AND 980), reconciled AS (SELECT s.* FROM cleaned s INNER JOIN matched_keys k ON s.supplier_id = k.supplier_id AND s.id = k.id), scored AS (SELECT id, tags, DENSE_RANK() OVER (ORDER BY cost DESC) AS cost_dense_rank FROM reconciled), scored_products AS (SELECT *, RANK() OVER w_part AS cost_dense_rank_rank FROM scored WINDOW w_part AS (ORDER BY cost_dense_rank ASC NULLS FIRST)), metrics AS (SELECT id, cost_dense_rank_rank, CUME_DIST() OVER w_hist AS cost_dense_rank_cume_dist, PERCENT_RANK() OVER w_ordered AS cost_dense_rank_rank_percent_rank, RANK() OVER w_hist AS cost_dense_rank_rank_2, PERCENT_RANK() OVER w_ordered AS cost_dense_rank_rank_percent_rank_2 FROM scored_products WHERE cost_dense_rank_rank IS NOT NULL WINDOW w_hist AS (ORDER BY cost_dense_rank DESC NULLS FIRST), w_ordered AS (ORDER BY cost_dense_rank_rank ASC NULLS LAST)), with_windows AS (SELECT cost_dense_rank_cume_dist, cost_dense_rank_rank_percent_rank, cost_dense_rank_rank_2, cost_dense_rank_rank_percent_rank_2, PERCENT_RANK() OVER (ORDER BY cost_dense_rank_rank ASC NULLS FIRST) AS cost_dense_rank_rank_percent_rank_3, DENSE_RANK() OVER w_ordered AS cost_dense_rank_cume_dist_dense_rank, PERCENT_RANK() OVER w_hist AS cost_dense_rank_rank_percent_rank_percent_rank, RANK() OVER (ORDER BY cost_dense_rank_rank_percent_rank_2 ASC NULLS FIRST) AS cost_dense_rank_rank_percent_rank_2_rank, PERCENT_RANK() OVER w_hist_2 AS cost_dense_rank_rank_percent_rank_percent_rank_2 FROM metrics WINDOW w_ordered AS (ORDER BY cost_dense_rank_cume_dist DESC), w_hist AS (ORDER BY cost_dense_rank_rank_percent_rank ASC NULLS LAST), w_hist_2 AS (ORDER BY cost_dense_rank_rank_percent_rank DESC NULLS LAST)), stats AS (SELECT CASE WHEN cost_dense_rank_cume_dist >= 0.67 THEN 'HIGH' ELSE 'LOW' END AS cost_dense_rank_cume_dist_tier, CASE WHEN cost_dense_rank_rank_percent_rank >= 0.87 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_dense_rank_rank_percent_rank_tier, ROUND(AVG(cost_dense_rank_rank_2), 2) AS avg_cost_dense_rank_rank_2, COUNT(*) AS cnt, APPROX_PERCENTILE(cost_dense_rank_rank_percent_rank_2_rank, 0.9) AS cost_dense_rank_rank_percent_rank_2_rank_p90, PERCENTILE_APPROX(cost_dense_rank_rank_percent_rank_2, ARRAY(0.25, 0.5, 0.75)) AS cost_dense_rank_rank_percent_rank_2_quartiles FROM with_windows GROUP BY CASE WHEN cost_dense_rank_cume_dist >= 0.67 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN cost_dense_rank_rank_percent_rank >= 0.87 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT cost_dense_rank_cume_dist_tier, cost_dense_rank_rank_percent_rank_tier, cnt FROM stats ORDER BY cost_dense_rank_cume_dist_tier ASC
